<?php
namespace App\Http\Controllers; use App\Models\{FreeReport,FreeReportTemplate}; use Illuminate\Http\Request; use Inertia\Inertia;
class FreeReportTemplateController extends Controller { public function index(){return Inertia::render('ReportTemplates/Index',['templates'=>FreeReportTemplate::latest()->get()]);} public function storeFromReport(Request $r,FreeReport $report){$data=$report->only(['title','location','license_name','license_description','participants','subject','content','findings','conclusions','observations','provider_signature_name','provider_signature_position','client_signature_name','client_signature_position']);$name=$r->validate(['name'=>['required','string','max:180']])['name'];FreeReportTemplate::create(['name'=>$name,'data'=>$data,'created_by'=>$r->user()->id]);return back()->with('success','Șablonul a fost salvat.');} public function destroy(FreeReportTemplate $freeReportTemplate){$freeReportTemplate->delete();return back()->with('success','Șablonul a fost șters.');} }
